problems.starterCode:
export function firstRestockItem<T>(_items: readonly T[]): T | undefined {
  return undefined;
}

problems.solutionCode:
export function firstRestockItem<T>(items: readonly T[]): T | undefined {
  if (items.length === 0) return undefined;
  return items[0];
}

problems.trapMutant:
export function firstRestockItem<T>(items: readonly T[]): T | null {
  return items[0] ?? null;
}

problems.starterCode:
export function copyManifestSnapshot<T extends object>(_record: T): T {
  return {} as T;
}

problems.solutionCode:
export function copyManifestSnapshot<T extends object>(record: T): T {
  return Object.assign({}, record);
}

problems.trapMutant:
export function copyManifestSnapshot<T extends object>(record: T): T {
  if (!("id" in record)) throw new Error('Manifest record requires an id');
  return { ...record };
}

problems.starterCode:
export function readInvoiceField<T extends object, K extends keyof T>(_record: T, _key: K): T[K] | undefined {
  return undefined;
}

problems.solutionCode:
export function readInvoiceField<T extends object, K extends keyof T>(record: T, key: K): T[K] | undefined {
  if (!Object.hasOwn(record, key)) return undefined;
  return record[key];
}

problems.trapMutant:
export function readInvoiceField<T extends object>(record: T, key: string): unknown {
  return key in record ? record[key as keyof T] : undefined;
}

