type ShipmentRecord = { shipmentCode: string; deliveredAt?: string };

export function projectShipmentField(shipments: readonly ShipmentRecord[], field: string): unknown[] {
  if (field === 'shipmentCode') return shipments.map((shipment) => shipment.shipmentCode);
  return [];
}

